with with_gaps as (select *, case when started_at - lag(started_at) over (partition by customer_id order by started_at, id) > interval '14' day then 1 else 0 end as new_group_flag from sessions), sessions_sessions as (select *, sum(new_group_flag) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as island_id from with_gaps) select case when new_group_flag >= 1 then 'PREMIUM' else 'STANDARD' end as new_group_flag_tier, count(*) as row_count, max(started_at) as last_seen, count_if(country = 'TH') as th_events from sessions_sessions group by 1 having count(*) > 1 order by row_count desc nulls last;
